class ExportPhase(IntEnum):
    """Export lifecycle phase."""
    #: Pages are still being appended.
    EXPORTING = 0
    #: The root is computed and published; the export is immutable.
    EXPORTED = 1

    @classmethod
    def from_scval(cls, value: Any) -> "ExportPhase":
        if value.kind == "vec" and len(value.value or []) == 1:
            value = value.value[0]
        if value.kind != "symbol":
            raise XdrError("expected a symbol for ExportPhase, got {value.kind}")
        tag = str(value.value)
        if tag == 'Exporting':
            return cls.EXPORTING
        if tag == 'Exported':
            return cls.EXPORTED
        raise XdrError(f"unknown ExportPhase variant {tag}")

    def to_scval(self) -> ScVal:
        if self == self.EXPORTING:
            return ScVal("vec", [ScVal("symbol", 'Exporting')])
        if self == self.EXPORTED:
            return ScVal("vec", [ScVal("symbol", 'Exported')])
        raise XdrError(f"unknown {enum.name} variant {self}")

class ImportPhase(IntEnum):
    """Import lifecycle phase."""
    #: Pages are still being imported.
    IMPORTING = 0
    #: Conservation asserted; the migration is complete and irreversible.
    IMPORTED = 1

    @classmethod
    def from_scval(cls, value: Any) -> "ImportPhase":
        if value.kind == "vec" and len(value.value or []) == 1:
            value = value.value[0]
