class IntentStatus(IntEnum):
    """Lifecycle state of a scheduled intent."""
    #: Authorized and (partially) executable; some occurrences remain.
    PENDING = 0
    #: Every occurrence has been materialized into a stream. Terminal.
    EXECUTED = 1
    #: Cancelled by the sender before the execution window opened. Terminal.
    CANCELLED = 2
    #: Passed `expires_at` with occurrences outstanding; escrow refunded.
    #: Terminal.
    EXPIRED = 3

    @classmethod
    def from_scval(cls, value: Any) -> "IntentStatus":
        if value.kind == "vec" and len(value.value or []) == 1:
            value = value.value[0]
        if value.kind != "symbol":
            raise XdrError("expected a symbol for IntentStatus, got {value.kind}")
        tag = str(value.value)
        if tag == 'Pending':
            return cls.PENDING
        if tag == 'Executed':
            return cls.EXECUTED
        if tag == 'Cancelled':
            return cls.CANCELLED
        if tag == 'Expired':
            return cls.EXPIRED
        raise XdrError(f"unknown IntentStatus variant {tag}")

    def to_scval(self) -> ScVal:
        if self == self.PENDING:
            return ScVal("vec", [ScVal("symbol", 'Pending')])
        if self == self.EXECUTED:
            return ScVal("vec", [ScVal("symbol", 'Executed')])
        if self == self.CANCELLED:
            return ScVal("vec", [ScVal("symbol", 'Cancelled')])
        if self == self.EXPIRED:
            return ScVal("vec", [ScVal("symbol", 'Expired')])
        raise XdrError(f"unknown {enum.name} variant {self}")

class OwnershipRole(IntEnum):
    """The role being handed over by a two-step ownership transfer."""
    #: The payer: may top up and cancel, and receives cancellation refunds.
    SENDER = 0
    #: The claimant: may withdraw accrued funds.
    RECIPIENT = 1

    @classmethod
    def from_scval(cls, value: Any) -> "OwnershipRole":
        if value.kind == "vec" and len(value.value or []) == 1:
            value = value.value[0]
        if value.kind != "symbol":
            raise XdrError("expected a symbol for OwnershipRole, got {value.kind}")
        tag = str(value.value)
        if tag == 'Sender':
            return cls.SENDER
        if tag == 'Recipient':
            return cls.RECIPIENT
        raise XdrError(f"unknown OwnershipRole variant {tag}")

    def to_scval(self) -> ScVal:
        if self == self.SENDER:
            return ScVal("vec", [ScVal("symbol", 'Sender')])
        if self == self.RECIPIENT:
            return ScVal("vec", [ScVal("symbol", 'Recipient')])
        raise XdrError(f"unknown {enum.name} variant {self}")

class StreamStatus(IntEnum):
    """Lifecycle state of a stream."""
    #: Running; funds accrue and can be withdrawn or topped up.
    ACTIVE = 0
    #: Cancelled; remaining funds were split at cancellation. Terminal.
    CANCELLED = 1
    #: Fully streamed and fully withdrawn. Terminal.
    DEPLETED = 2

    @classmethod
    def from_scval(cls, value: Any) -> "StreamStatus":
        if value.kind == "vec" and len(value.value or []) == 1:
            value = value.value[0]
        if value.kind != "symbol":
            raise XdrError("expected a symbol for StreamStatus, got {value.kind}")
        tag = str(value.value)
        if tag == 'Active':
            return cls.ACTIVE
        if tag == 'Cancelled':
            return cls.CANCELLED
        if tag == 'Depleted':
            return cls.DEPLETED
        raise XdrError(f"unknown StreamStatus variant {tag}")

    def to_scval(self) -> ScVal:
        if self == self.ACTIVE:
            return ScVal("vec", [ScVal("symbol", 'Active')])
        if self == self.CANCELLED:
            return ScVal("vec", [ScVal("symbol", 'Cancelled')])
        if self == self.DEPLETED:
            return ScVal("vec", [ScVal("symbol", 'Depleted')])
        raise XdrError(f"unknown {enum.name} variant {self}")

