    start_time: int
    #: Last timestamp this segment accrues at (exclusive).
    end_time: int
    #: Tokens reserved for the window, as of the segment being accepted.
    allocation: int
    #: Divisor of the pro-rata term; see the struct docs.
    basis_seconds: int

    @classmethod
    def from_native(cls, value: Any) -> "RateSegment":
        fields = scval_to_struct(value)
        return cls(
            start_time=_decode_value('u64', fields['start_time']),
            end_time=_decode_value('u64', fields['end_time']),
            allocation=_decode_value('i128', fields['allocation']),
            basis_seconds=_decode_value('u64', fields['basis_seconds']),
        )

    def to_scval(self) -> ScVal:
        return ScVal("map", [
            (ScVal("symbol", 'start_time'), _encode_value('u64', self.start_time)),
            (ScVal("symbol", 'end_time'), _encode_value('u64', self.end_time)),
            (ScVal("symbol", 'allocation'), _encode_value('i128', self.allocation)),
            (ScVal("symbol", 'basis_seconds'), _encode_value('u64', self.basis_seconds)),
        ])

