def _expect(value: Any, kind: str, label: str) -> Any:
    if value.kind != kind:
        raise XdrError(f"{label}: expected {kind}, got {value.kind}")
    return value.value


def _integer(value: Any, label: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise XdrError(f"{label} must be an integer")
    return value


def _scval_u32(value: Any, label: str) -> int:
    return int(_expect(value, "u32", label))


def _encode_value(type_label: str, value: Any) -> ScVal:
    if type_label.startswith("vec:"):
        if not isinstance(value, (list, tuple)):
            raise XdrError(f"{type_label} must be a sequence")
        inner = type_label[4:]
        return ScVal("vec", [_encode_value(inner, item) for item in value])
    if type_label.startswith("option:"):
        if value is None:
            return ScVal("void")
        return _encode_value(type_label[7:], value)
    if type_label == "address":
        return address_to_scval(value)
    if type_label == "bool":
        if not isinstance(value, bool):
            raise XdrError("bool must be a boolean")
        return bool_to_scval(value)
    if type_label == "u32":
        return ScVal("u32", _integer(value, type_label))
    if type_label == "i32":
        return ScVal("i32", _integer(value, type_label))
    if type_label == "u64":
        return u64_to_scval(_integer(value, type_label))
    if type_label == "i128":
        return i128_to_scval(_integer(value, type_label))
    if type_label == "u128":
        return ScVal("u128", _integer(value, type_label))
    if type_label in ("string", "symbol"):
        if not isinstance(value, str):
            raise XdrError(f"{type_label} must be a string")
        return ScVal(type_label, value)
    if type_label in ("bytes32", "bytes64"):
        width = int(type_label[5:])
        if not isinstance(value, bytes) or len(value) != width:
            raise XdrError(f"{type_label} must be {width} bytes")
        return ScVal("bytes", value)
    if type_label == "void":
        return ScVal("void")
    return _encode_named(type_label, value)


def _decode_value(type_label: str, value: Any) -> Any:
    if type_label.startswith("vec:"):
        items = list(_expect(value, "vec", type_label) or [])
        return [_decode_value(type_label[4:], item) for item in items]
    if type_label.startswith("option:"):
        if value.kind == "void":
            return None
        return _decode_value(type_label[7:], value)
    if type_label == "void":
        _expect(value, "void", type_label)
        return None
    if type_label == "address":
        return scval_to_address(value)
    if type_label == "bool":
        return scval_to_bool(value)
    if type_label == "u32":
        return _scval_u32(value, type_label)
    if type_label == "i32":
        return int(_expect(value, "i32", type_label))
    if type_label == "u64":
        return scval_to_u64(value)
    if type_label == "i128":
        return scval_to_i128(value)
    if type_label == "u128":
        return int(_expect(value, "u128", type_label))
    if type_label == "string":
        return str(_expect(value, "string", type_label))
    if type_label == "symbol":
        return str(_expect(value, "symbol", type_label))
    if type_label in ("bytes32", "bytes64"):
        width = int(type_label[5:])
        raw = bytes(_expect(value, "bytes", type_label))
        if len(raw) != width:
            raise XdrError(f"{type_label}: expected {width} bytes, got {len(raw)}")
        return raw
    return _decode_named(type_label, value)


def _encode_named(name: str, value: Any) -> ScVal:
    if name in _ENUM_TYPES:
        if not isinstance(value, _ENUM_TYPES[name]):
            raise XdrError(f"{name} expects {_ENUM_TYPES[name].__name__}")
        return value.to_scval()
    if name in _STRUCT_TYPES:
        if not isinstance(value, _STRUCT_TYPES[name]):
            raise XdrError(f"{name} expects {_STRUCT_TYPES[name].__name__}")
        return value.to_scval()
    if name in _UNION_TYPES:
        for case_name, case_type, labels in _UNION_TYPES[name]:
            if isinstance(value, case_type):
                payload = [ScVal("symbol", case_name)]
                if len(labels) == 1:
                    payload.append(_encode_value(labels[0], value.value))
                elif labels:
                    values = value.values
                    if not isinstance(values, (list, tuple)) or len(values) != len(labels):
                        raise XdrError(
                            f"{name}.{case_name}: expected {len(labels)} payload values, "
                            f"got {len(values) if isinstance(values, (list, tuple)) else 'non-sequence'}"
                        )
                    payload.extend(
                        _encode_value(label, item)
                        for label, item in zip(labels, values)
                    )
                return ScVal("vec", payload)
        raise XdrError(f"{name} has an unknown payload type")
    raise XdrError(f"unknown generated type {name}")


def _decode_named(name: str, value: Any) -> Any:
    if name in _ENUM_TYPES:
        return _ENUM_TYPES[name].from_scval(value)
    if name in _STRUCT_TYPES:
        return _STRUCT_TYPES[name].from_native(value)
    if name in _UNION_TYPES:
        return _decode_union(name, value)
    raise XdrError(f"unknown generated type {name}")


def _decode_union(name: str, value: Any) -> Any:
    items = list(_expect(value, "vec", name) or [])
    if not items or items[0].kind != "symbol":
        raise XdrError(f"{name} must start with a symbol variant")
    variant = str(items[0].value)
    for case_name, case_type, labels in _UNION_TYPES[name]:
        if case_name != variant:
            continue
        if len(items) != len(labels) + 1:
            raise XdrError(
                f"{name}.{case_name}: expected {len(labels) + 1} values, got {len(items)}"
            )
        decoded = [
            _decode_value(label, item)
            for label, item in zip(labels, items[1:])
        ]
        if not decoded:
            return case_type()
        if len(decoded) == 1:
            return case_type(decoded[0])
        return case_type(tuple(decoded))
    raise XdrError(f"unknown {name} variant {variant}")


def _error_from_scval(value: Any) -> StreamError:
    code = int(_expect(value, "error", "contract error"))
    error = contract_error(code)
    if error is None:
        raise XdrError(f"unknown contract error code {code}")
    return error


def _decode_result_vec(type_label: str, value: Any) -> list[Any]:
    items = list(_expect(value, "vec", type_label) or [])
    return [
        _error_from_scval(item) if item.kind == "error" else _decode_value(type_label, item)
        for item in items
    ]


def _decode_call_result(type_label: str, value: Any) -> Any:
    if type_label.startswith("vec:result:"):
        return _decode_result_vec(type_label[11:], value)
    if type_label.startswith("result:"):
        if value.kind == "error":
            return _error_from_scval(value)
        return _decode_value(type_label[8:], value)
    if value.kind == "error":
        return _error_from_scval(value)
    return _decode_value(type_label, value)


def _event_topic(event: ContractEvent, index: int, name: str) -> Any:
    if index >= len(event.topics):
        raise XdrError(f"event {name} is missing topic {index}")
    return event.topics[index]


def _event_data(event: ContractEvent, name: str, field: str) -> Any:
    return event.data.get(field, ScVal("void"))

