T = TypeVar("T")


class ReadOnlyMethods:
    """Typed read-only calls over a host that implements ``_read``."""

    def _read(
        self, method: str, args: list[ScVal], decode: Callable[[Any], T]
    ) -> T:
        raise NotImplementedError

    """Returns the stream-NFT contract linked to `stream_id` at atomic
creation, or `None` when the stream was created without a linked NFT."""
    def stream_nft_link(self, stream_id: int) -> str | None:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['streamNftLink'], args, decode_stream_nft_link_result)

    """Read-only view of a stream's pending ownership proposal, if any.
Reading extends the proposal's storage TTL; unknown streams simply
return `None`."""
    def pending_ownership_transfer(self, stream_id: int) -> PendingOwnership | None:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['pendingOwnershipTransfer'], args, decode_pending_ownership_transfer_result)

    """Read-only view of a stream's pending sender transfer, if any."""
    def pending_sender_transfer(self, stream_id: int) -> PendingSenderTransfer | None:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['pendingSenderTransfer'], args, decode_pending_sender_transfer_result)

    """The append-only sender-role log of a stream: who held the payer role at
creation and every consented hop since. Never rewritten, so the answer to
"who funded this deposit?" survives any number of transfers."""
    def sender_history(self, stream_id: int) -> SenderHistory:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['senderHistory'], args, decode_sender_history_result)

    """The address that receives the refund of the unstreamed remainder when the
stream is cancelled. Equal to the current sender unless a sender transfer
left the claim behind (or an amendment moved it on purpose)."""
    def refund_target(self, stream_id: int) -> str:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['refundTarget'], args, decode_refund_target_result)

    """Read-only view of a stream's pending rate proposal, if any.
Reading extends the proposal's storage TTL; unknown streams return
`None`."""
    def pending_rate_change(self, stream_id: int) -> PendingRateChange | None:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['pendingRateChange'], args, decode_pending_rate_change_result)

    """Read-only view of a stream's rate schedule. Empty means the stream
still accrues at its original rate over `[start_time, end_time)`: the
single-window formula, with no stored segment to consult."""
    def rate_segments(self, stream_id: int) -> list[RateSegment]:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['rateSegments'], args, decode_rate_segments_result)

    """Read-only view of a stream's full state."""
    def get_stream(self, stream_id: int) -> Stream:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['getStream'], args, decode_get_stream_result)

    """Read-only view of an address's non-transferable reputation
record plus its raw and inactivity-decayed scores (issue #574).

Never reverts: an address with no settled history reads as a
zero record with score 0. The completion half of the record is
derived from the address's stream history (a bounded scan; see
reputation.rs for the cost model). There is
deliberately no transfer/approval entrypoint — the score is
bound to the address that earned it."""
    def get_reputation(self, subject: str) -> ReputationView:
        args = [
            _encode_value('address', subject),
        ]
        return self._read(METHODS['getReputation'], args, decode_get_reputation_result)

    """The address's current (inactivity-decayed) reputation score in
`0..=1000` — the cheap scalar read integrators gate access on."""
    def reputation_score(self, subject: str) -> int:
        args = [
            _encode_value('address', subject),
        ]
        return self._read(METHODS['reputationScore'], args, decode_reputation_score_result)

    """Read-only view of a stream's open dispute. Reverts with
[`StreamError::DisputeNotFound`] when the stream is undisputed
(disputes exist only while open; resolution and expiry remove them)."""
    def get_dispute(self, stream_id: int) -> Dispute:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['getDispute'], args, decode_get_dispute_result)

    """The bond a recipient must post (and pre-approve) to raise the next
dispute on this stream: 5% of the deposit, multiplied by the number
of disputes already raised on it, floored at one token unit."""
    def required_dispute_bond(self, stream_id: int) -> int:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['requiredDisputeBond'], args, decode_required_dispute_bond_result)

    """Read-only view of the accrued-but-unwithdrawn balance at the current
ledger time. Zero before `start_time` and for cancelled streams; the
full remainder at or after `end_time`."""
    def available(self, stream_id: int) -> int:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['available'], args, decode_available_result)

    """A page of stream ids where `recipient` is the recipient, in creation
order (oldest first). `limit` is clamped to `MAX_PAGE_SIZE`; paginate
by advancing `offset`. Unknown addresses yield an empty page.

Discovery view only: it does not authorize anything and terminal
(cancelled/depleted) streams keep their ids — read each stream's
`status` for lifecycle state."""
    def recipient_streams(self, recipient: str, offset: int, limit: int) -> list[int]:
        args = [
            _encode_value('address', recipient),
            _encode_value('u32', offset),
            _encode_value('u32', limit),
        ]
        return self._read(METHODS['recipientStreams'], args, decode_recipient_streams_result)

    """A page of stream ids created by `sender`, in creation order. Same
pagination and advisory semantics as [`StreamingPayments::recipient_streams`]."""
    def sender_streams(self, sender: str, offset: int, limit: int) -> list[int]:
        args = [
            _encode_value('address', sender),
            _encode_value('u32', offset),
            _encode_value('u32', limit),
        ]
        return self._read(METHODS['senderStreams'], args, decode_sender_streams_result)

    """Read-only view of a scheduled intent's full state."""
    def get_intent(self, intent_id: int) -> ScheduledIntent:
        args = [
            _encode_value('u64', intent_id),
        ]
        return self._read(METHODS['getIntent'], args, decode_get_intent_result)

    """A page of scheduled-intent ids created by `sender`, in creation order.
Same pagination and advisory semantics as
[`StreamingPayments::sender_streams`]."""
    def sender_intents(self, sender: str, offset: int, limit: int) -> list[int]:
        args = [
            _encode_value('address', sender),
            _encode_value('u32', offset),
            _encode_value('u32', limit),
        ]
        return self._read(METHODS['senderIntents'], args, decode_sender_intents_result)

    """One-call treasury snapshot for `token`: governor, pending nominee,
current fee configuration, and the fee ledger totals that must
reconcile with the `FeeCharged` / `FeeWithdrawn` event streams.
Public, read-only, no auth."""
    def treasury_status(self, token: str) -> TreasuryStatus:
        args = [
            _encode_value('address', token),
        ]
        return self._read(METHODS['treasuryStatus'], args, decode_treasury_status_result)

    """The protocol fee charged for `stream_id` at creation, in smallest
token units. Zero for streams created while fees were disabled (or
whose fee rounded to zero). Reverts with
[`StreamError::StreamNotFound`] for unknown ids."""
    def stream_fee(self, stream_id: int) -> int:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['streamFee'], args, decode_stream_fee_result)

    """One bounded page of the fee verification scan: sums stored
per-stream fees for `token` over a window of the stream-id space
(`count` clamped to [`MAX_PAGE_SIZE`]). Page from id 1 until `done`
is true; the summed `fees_in_range` values must equal
`treasury_status(token).charged_total` — and both must equal the
amounts in the contract's `FeeCharged` events. That three-way
equality is the treasury invariant, verifiable by anyone from
public reads alone (see `scripts/verify-fees.ts`)."""
    def verify_treasury(self, token: str, start_id: int, count: int) -> FeeScan:
        args = [
            _encode_value('address', token),
            _encode_value('u64', start_id),
            _encode_value('u32', count),
        ]
        return self._read(METHODS['verifyTreasury'], args, decode_verify_treasury_result)

    """Number of streams ever created (ids are `1..=total_streams()`).
Public convenience for verifiers to know the scan range."""
    def total_streams(self) -> int:
        args = []
        return self._read(METHODS['totalStreams'], args, decode_total_streams_result)

    """Reads a sponsor's budget configuration, if any."""
    def get_sponsor(self, sponsor: str) -> SponsorConfig | None:
        args = [
            _encode_value('address', sponsor),
        ]
        return self._read(METHODS['getSponsor'], args, decode_get_sponsor_result)

    """Reads a beneficiary's enrolled consent key, if any."""
    def get_beneficiary_public_key(self, beneficiary: str) -> bytes | None:
        args = [
            _encode_value('address', beneficiary),
        ]
        return self._read(METHODS['getBeneficiaryPublicKey'], args, decode_get_beneficiary_public_key_result)

    """The sponsor's current-window spend."""
    def sponsor_period_spend(self, sponsor: str) -> PeriodSpend:
        args = [
            _encode_value('address', sponsor),
        ]
        return self._read(METHODS['sponsorPeriodSpend'], args, decode_sponsor_period_spend_result)

    """A beneficiary's spend within a sponsor's current window."""
    def beneficiary_spend(self, sponsor: str, beneficiary: str) -> PeriodSpend:
        args = [
            _encode_value('address', sponsor),
            _encode_value('address', beneficiary),
        ]
        return self._read(METHODS['beneficiarySpend'], args, decode_beneficiary_spend_result)

    """Returns the current policy admin, if initialized."""
    def policy_admin(self) -> str | None:
        args = []
        return self._read(METHODS['policyAdmin'], args, decode_policy_admin_result)

    """Returns the pending policy admin nominee, if any."""
    def policy_pending_admin(self) -> str | None:
        args = []
        return self._read(METHODS['policyPendingAdmin'], args, decode_policy_pending_admin_result)

    """Returns the on-chain timelock delay in seconds."""
    def policy_timelock_delay(self) -> int:
        args = []
        return self._read(METHODS['policyTimelockDelay'], args, decode_policy_timelock_delay_result)

    """Read-only check whether `asset` is currently allowed for new streams."""
    def policy_is_asset_allowed(self, asset: str) -> bool:
        args = [
            _encode_value('address', asset),
        ]
        return self._read(METHODS['policyIsAssetAllowed'], args, decode_policy_is_asset_allowed_result)

    """Returns the queued allowlist change for `asset`, if any."""
    def policy_get_queued_asset(self, asset: str) -> QueuedAssetChange | None:
        args = [
            _encode_value('address', asset),
        ]
        return self._read(METHODS['policyGetQueuedAsset'], args, decode_policy_get_queued_asset_result)

    """Queries the effective stream policy for `token` (falling back to global policy if unset)."""
    def get_stream_policy(self, token: str | None) -> StreamPolicy | None:
        args = [
            _encode_value('option:address', token),
        ]
        return self._read(METHODS['getStreamPolicy'], args, decode_get_stream_policy_result)

    """Returns the current schema version of stored contract state."""
    def schema_version(self) -> int:
        args = []
        return self._read(METHODS['schemaVersion'], args, decode_schema_version_result)

    """Returns whether mutating contract operations are currently frozen."""
    def is_frozen(self) -> bool:
        args = []
        return self._read(METHODS['isFrozen'], args, decode_is_frozen_result)

    """Read-only view of any pending upgrade proposal."""
    def pending_upgrade(self) -> PendingUpgrade | None:
        args = []
        return self._read(METHODS['pendingUpgrade'], args, decode_pending_upgrade_result)

    """Read-only snapshot of storage migration progress."""
    def migration_progress(self) -> MigrationStatus:
        args = []
        return self._read(METHODS['migrationProgress'], args, decode_migration_progress_result)

    """The storage layout version of a single stream record.

`1` is the legacy untagged layout (a bare `Stream` map), `2` the
version-tagged [`VersionedStream`] every current write produces. Auditors
use this to answer "what still needs moving?" per stream without
decoding the record itself; see `scripts/migrate_audit.ts` for the
off-chain walk.

Fails closed with [`StreamError::SchemaVersionUnsupported`] for a record
tagged with a layout this build does not understand, and with
[`StreamError::StreamNotFound`] when no record exists."""
    def stream_record_version(self, stream_id: int) -> int:
        args = [
            _encode_value('u64', stream_id),
        ]
        return self._read(METHODS['streamRecordVersion'], args, decode_stream_record_version_result)

    """Resolves reference timestamp for a given stream id and oracle flag."""
    def resolve_time(self, stream_id: int, use_oracle: bool) -> ResolvedTime:
        args = [
            _encode_value('u64', stream_id),
            _encode_value('bool', use_oracle),
        ]
        return self._read(METHODS['resolveTime'], args, decode_resolve_time_result)

    """Reads current oracle configuration."""
    def oracle_config(self) -> OracleConfig | None:
        args = []
        return self._read(METHODS['oracleConfig'], args, decode_oracle_config_result)

    """Reads latest report from a publisher."""
    def oracle_report(self, publisher: str) -> OracleReport | None:
        args = [
            _encode_value('address', publisher),
        ]
        return self._read(METHODS['oracleReport'], args, decode_oracle_report_result)

    """Whether the timelock has taken over the admin entry points."""
    def governance_is_initialized(self) -> bool:
        args = []
        return self._read(METHODS['governanceIsInitialized'], args, decode_governance_is_initialized_result)

    """The current signer set."""
    def governance_signers(self) -> list[str]:
        args = []
        return self._read(METHODS['governanceSigners'], args, decode_governance_signers_result)

    """The configured veto window in seconds."""
    def governance_veto_window(self) -> int:
        args = []
        return self._read(METHODS['governanceVetoWindow'], args, decode_governance_veto_window_result)

    """Reads a proposal: its window, recorded signatures and terminal flags."""
    def governance_proposal(self, proposal_id: int) -> Proposal | None:
        args = [
            _encode_value('u64', proposal_id),
        ]
        return self._read(METHODS['governanceProposal'], args, decode_governance_proposal_result)

    """The next proposal id, for clients that want to follow the queue."""
    def governance_proposal_count(self) -> int:
        args = []
        return self._read(METHODS['governanceProposalCount'], args, decode_governance_proposal_count_result)

